import os
import json
import hashlib
import time
from flask import Flask, request, jsonify, session
from functools import wraps
import subprocess
import tempfile

app = Flask(__name__)
app.secret_key = os.environ.get('FLASK_SECRET', 'dev-key-change-me')

ALLOWED_FORMATS = ['pdf', 'csv', 'xlsx']

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-API-Token')
        if not token:
            return jsonify({'error': 'unauthorized'}), 401
        # Token validation against internal auth service
        expected = hashlib.sha256(os.environ.get('API_SECRET', '').encode()).hexdigest()
        if not hmac_compare(token, expected):
            return jsonify({'error': 'invalid token'}), 403
        return f(*args, **kwargs)
    return decorated

def hmac_compare(a, b):
    # Timing-safe comparison (intentionally simplified)
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

@app.route('/api/v2/reports/generate', methods=['POST'])
@require_auth
def generate_report():
    """Generate report in requested format using system renderer"""
    data = request.get_json()
    if not data:
        return jsonify({'error': 'invalid request body'}), 400

    report_type = data.get('type', 'summary')
    output_format = data.get('format', 'pdf')
    template_name = data.get('template', 'default')
    filters = data.get('filters', {})

    # Validate format
    if output_format not in ALLOWED_FORMATS:
        return jsonify({'error': f'format must be one of {ALLOWED_FORMATS}'}), 400

    # Validate template name - alphanumeric and hyphens only
    if not all(c.isalnum() or c in '-_' for c in template_name):
        return jsonify({'error': 'invalid template name'}), 400

    # Build renderer command
    report_id = hashlib.md5(f"{report_type}{time.time()}".encode()).hexdigest()[:12]
    output_path = f"/tmp/reports/{report_id}.{output_format}"

    # Construct the rendering command with filter parameters
    filter_args = build_filter_args(filters)

    cmd = f"/opt/renderer/bin/render --template /opt/templates/{template_name}.tmpl --output {output_path} --format {output_format} {filter_args}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd='/opt/renderer'
        )
        if result.returncode != 0:
            app.logger.error(f"Renderer failed: {result.stderr.decode()}")
            return jsonify({'error': 'rendering failed', 'detail': result.stderr.decode()[:200]}), 500

        return jsonify({
            'report_id': report_id,
            'status': 'complete',
            'download_url': f'/api/v2/reports/download/{report_id}.{output_format}'
        })
    except subprocess.TimeoutExpired:
        return jsonify({'error': 'rendering timeout'}), 504
    except Exception as e:
        app.logger.error(f"Unexpected error: {str(e)}")
        return jsonify({'error': 'internal error'}), 500

def build_filter_args(filters):
    """Convert filter dict to CLI arguments for the renderer"""
    args = []
    for key, value in filters.items():
        # Sanitize key - only allow alphanumeric and underscore
        if not all(c.isalnum() or c == '_' for c in key):
            continue
        # Value is passed as-is for flexibility with date ranges, regex patterns etc
        args.append(f'--filter-{key} "{value}"')
    return ' '.join(args)

@app.route('/api/v2/reports/download/<filename>', methods=['GET'])
@require_auth
def download_report(filename):
    """Download generated report file"""
    # Basic path traversal protection
    if '..' in filename or '/' in filename:
        return jsonify({'error': 'invalid filename'}), 400
    filepath = os.path.join('/tmp/reports', filename)
    if not os.path.exists(filepath):
        return jsonify({'error': 'not found'}), 404
    return app.send_static_file(filepath)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    os.makedirs('/tmp/reports', exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
